"""The Home Assistant broker: what the asterisk user may still ask for.

    python3 -m pytest switchboard/tests/test_ha_broker.py

Since v0.110.0 nothing running as the asterisk user holds the Supervisor token.
These tests pin both halves:
  * every request those programs actually make is accepted (generated by calling
    the real ha_client functions, so the allow-list cannot drift from the code);
  * everything else the token could do is refused;
and the plumbing that keeps the token out of their reach (run scripts, the s6
environment directory, the socket's mode).
"""
import json
import os
import re
import socket
import sys
import tempfile
import threading
import time
from importlib.machinery import SourceFileLoader
from pathlib import Path

ADDON = Path(__file__).resolve().parents[1]
WEBUI = ADDON / "rootfs" / "usr" / "share" / "switchboard" / "webui"
sys.path.insert(0, str(WEBUI))
ha_client = SourceFileLoader("ha_client", str(WEBUI / "ha_client.py")).load_module()
sys.modules["ha_client"] = ha_client
broker = SourceFileLoader("ha_broker", str(WEBUI / "ha_broker.py")).load_module()
broker._lan_ip = lambda: "192.0.2.10"          # this host, as the AGI would see it

S6 = ADDON / "rootfs" / "etc" / "s6-overlay" / "s6-rc.d"
AGI = ADDON / "rootfs" / "var" / "lib" / "asterisk" / "agi-bin"
CLIP = "http://192.0.2.10:8099/announce/a1234567890.wav"

# Every program that runs as the asterisk user and talks to Home Assistant, and
# the shared modules they import for it.
UID100_SOURCES = [AGI / n for n in (
    "switchboard-announce.agi", "switchboard-assistant.agi", "switchboard-automation.agi",
    "switchboard-wakeup-deliver.agi", "switchboard-status.agi")] + [
    ADDON / "rootfs" / "usr" / "bin" / "switchboard-callqos",
    WEBUI / "ha_reports.py", WEBUI / "weather.py"]
# ha_client functions the broker serves, i.e. those exercised in record_calls().
COVERED = {"available", "get_lights", "lights_by_area", "get_light_state", "set_light",
           "get_state", "get_states", "converse", "call_service", "resolve_entities",
           "entity_exists", "set_state", "notify", "ha_location", "get_calendar_events",
           "is_light_entity", "is_entity_id"}


def record_calls():
    """The (method, path, body) of every request the uid-100 programs make."""
    seen = []
    real = ha_client._request
    ha_client._request = lambda m, p, b=None: seen.append((m, p, b)) or (200, "[]")
    try:
        ha_client.available()
        ha_client.get_lights()
        ha_client.lights_by_area()
        ha_client.get_light_state("light.kitchen")
        ha_client.set_light("light.kitchen", True)
        ha_client.set_light("light.kitchen", False)
        ha_client.get_state("sensor.outside_temperature")
        ha_client.get_states()
        ha_client.resolve_entities(["media_player.kitchen"])
        ha_client.entity_exists("scene.morning")
        ha_client.converse("turn on the porch light")
        ha_client.call_service("scene", "turn_on", {"entity_id": "scene.morning"})
        ha_client.call_service("media_player", "play_media", {
            "entity_id": ["media_player.kitchen", "media_player.den"],
            "media_content_id": CLIP, "media_content_type": "music"})
        ha_client.set_state("sensor.switchboard_last_call", 3.7, {"ext": "11", "mos": 4.1})
        ha_client.notify("Call quality was poor", title="Switchboard call quality",
                         notification_id="Switchboard callqos 11")
        ha_client.ha_location()
        ha_client.get_calendar_events("calendar.home", "2026-10-13T06:00:00-07:00",
                                      "2026-10-14T06:00:00+00:00")
    finally:
        ha_client._request = real
    return seen


def test_every_request_the_asterisk_user_makes_is_accepted():
    calls = record_calls()
    assert len(calls) >= 17, calls
    for method, path, body in calls:
        assert broker.check(method, path, body) is None, (method, path, body, broker.check(method, path, body))


def test_the_uid100_programs_use_only_covered_functions():
    used = set()
    for src in UID100_SOURCES:
        used |= set(re.findall(r"ha_client\.([a-z_]+)\(", src.read_text()))
    assert used, "no ha_client use found; the source list is stale"
    assert used <= COVERED, sorted(used - COVERED)


def test_their_service_calls_are_the_allowed_pairs():
    pairs = set()
    for src in UID100_SOURCES:
        pairs |= set(re.findall(r'call_service\(\s*"([a-z_]+)",\s*"([a-z_]+)"', src.read_text()))
    assert pairs, "no call_service literals found"
    assert pairs <= broker.SERVICES, sorted(pairs - broker.SERVICES)


REFUSED = [
    ("POST", "/services/notify/mobile_app_phone", {"message": "x"}),        # push stays root-only
    ("POST", "/services/shell_command/anything", {}),
    ("POST", "/services/homeassistant/restart", {}),
    ("POST", "/services/hassio/addon_stop", {"addon": "x"}),
    ("POST", "/services/tts/speak", {"entity_id": "tts.x"}),                  # in ha_client's list, not needed
    ("POST", "/services/climate/set_temperature", {"entity_id": "climate.x"}),
    ("POST", "/services/light/toggle", {"entity_id": "light.kitchen"}),
    ("POST", "/services/light/turn_on", {"entity_id": "switch.kitchen"}),
    ("POST", "/services/light/turn_on", {"entity_id": "light.kitchen", "brightness": 255}),
    ("POST", "/services/scene/turn_on", {"entity_id": "script.anything"}),
    ("POST", "/services/scene/apply", {"entities": {}}),
    ("POST", "/services/media_player/play_media", {"entity_id": "media_player.k",
     "media_content_id": "http://example.com/x.mp3", "media_content_type": "music"}),
    ("POST", "/services/media_player/play_media", {"entity_id": "media_player.k",
     "media_content_id": CLIP, "media_content_type": "video"}),
    ("POST", "/services/conversation/process?return_response=true",
     {"text": "hi", "agent_id": "conversation.chatgpt", "language": "en"}),
    ("POST", "/services/conversation/process", {"text": "hi"}),
    ("POST", "/template", {"template": "{{ states | list }}"}),
    ("POST", "/states/sensor.other", {"state": "1"}),
    ("POST", "/states/sensor.switchboard_last_call", {"state": 1}),
    ("POST", "/states/sensor.switchboard_last_call", {"state": "1", "context": {}}),
    ("POST", "/services/persistent_notification/create", {"message": "x", "data": {}}),
    ("POST", "/events/anything", {}),
    ("POST", "/config/core/check_config", None),
    ("GET", "/states/../config", None),
    ("GET", "/states/sensor.x?y=1", None),
    ("GET", "/history/period", None),
    ("GET", "/error_log", None),
    ("GET", "/calendars/sensor.x?start=2026-10-13T00:00:00&end=2026-10-14T00:00:00", None),
    ("GET", "/calendars/calendar.home?start=2026-10-13T00:00:00&end=x&extra=1", None),
    ("GET", "/states", {"x": 1}),
    ("DELETE", "/states/sensor.switchboard_last_call", None),
    ("GET", "http://supervisor/addons", None),
    (None, "/states", None),
    # path hygiene: a fragment, CR/LF (a second request line), a space, a backslash
    ("GET", "/states/light.kitchen#x", None),
    ("GET", "/states/light.kitchen\r\nX-Injected: 1", None),
    ("GET", "/states/light.kitchen HTTP/1.1", None),
    ("GET", "/states\\light.kitchen", None),
    # a well-formed calendar range plus one more parameter
    ("GET", "/calendars/calendar.home?start=2026-10-13T00:00:00&end=2026-10-14T00:00:00&x=2026-10-15T00:00:00", None),
    # a valid POST body under another method
    ("PUT", "/services/light/turn_on", {"entity_id": "light.kitchen"}),
    ("PATCH", "/states/sensor.switchboard_last_call", {"state": "1"}),
]


def test_everything_else_is_refused():
    for method, path, body in REFUSED:
        assert broker.check(method, path, body), (method, path, body)


def test_a_refused_request_never_reaches_home_assistant():
    forwarded = []
    fake = lambda m, p, b: forwarded.append((m, p)) or (200, "ok")
    assert broker.handle_line(b"not json", fake) == {"refused": "not JSON"}
    reply = broker.handle_line(json.dumps({"method": "POST", "path": "/services/homeassistant/restart",
                                           "body": {}}).encode(), fake)
    assert "refused" in reply and forwarded == []
    fake_states = lambda m, p, b: forwarded.append((m, p)) or (200, "[]")
    reply = broker.handle_line(json.dumps({"method": "GET", "path": "/states", "body": None}).encode(), fake_states)
    assert reply == {"status": 200, "text": "[]"} and forwarded == [("GET", "/states")]


def _serve(tmp: Path, forward, allowed_uids=None):
    path = str(tmp / "ha.sock")
    server = broker.make_server(path)
    server.forward = forward
    if sys.platform != "linux":          # no SO_PEERCRED off Linux; CI exercises the real one
        server.peer_uid = lambda sock: os.getuid()
    server.allowed_uids = {os.getuid()} if allowed_uids is None else allowed_uids
    threading.Thread(target=server.serve_forever, daemon=True).start()
    return server, path


def _client(path):
    env = {k: os.environ.pop(k, None) for k in ("SUPERVISOR_TOKEN", "HA_BASE_URL")}
    old = ha_client.BROKER_SOCKET
    ha_client.BROKER_SOCKET = path
    ha_client._cached, ha_client._dead_until = None, 0.0
    return env, old


def _restore(env, old):
    ha_client.BROKER_SOCKET = old
    ha_client._cached, ha_client._dead_until = None, 0.0
    for k, v in env.items():
        if v is not None:
            os.environ[k] = v


def test_a_process_without_the_token_goes_through_the_broker():
    tmp = Path(tempfile.mkdtemp())
    seen = []
    fwd = lambda m, p, b: seen.append((m, p)) or (200, json.dumps({"entity_id": "light.kitchen", "state": "on", "attributes": {}}))
    server, path = _serve(tmp, fwd)
    env, old = _client(path)
    try:
        assert oct(os.stat(path).st_mode & 0o777) == oct(0o660)
        assert ha_client.get_state("light.kitchen") == {"entity_id": "light.kitchen", "state": "on", "attributes": {}}
        assert seen == [("GET", "/states/light.kitchen")]
        # Allowed by ha_client's own domain list, refused by the broker: reads as
        # Home Assistant saying no, never reaches it.
        assert ha_client.call_service("tts", "speak", {"entity_id": "tts.x"}) is False
        assert len(seen) == 1
        # A refusal is "Home Assistant said no", not "unreachable": the very next
        # allowed call still goes through instead of waiting out the back-off.
        assert ha_client.get_state("light.kitchen") is not None
        assert len(seen) == 2
    finally:
        _restore(env, old)
        server.shutdown()
        server.server_close()


def test_a_refusal_first_does_not_make_the_client_back_off():
    # On a fresh client a refusal, read wrongly as "unreachable", would start the
    # 20 s back-off and silence the next, allowed call.
    tmp = Path(tempfile.mkdtemp())
    seen = []
    server, path = _serve(tmp, lambda m, p, b: seen.append(p) or (200, json.dumps({"entity_id": "light.kitchen", "state": "on"})))
    env, old = _client(path)
    try:
        assert ha_client.call_service("tts", "speak", {"entity_id": "tts.x"}) is False
        assert ha_client.get_state("light.kitchen") == {"entity_id": "light.kitchen", "state": "on", "attributes": {}}
        assert seen == ["/states/light.kitchen"]
    finally:
        _restore(env, old)
        server.shutdown()
        server.server_close()


def test_a_peer_outside_root_and_asterisk_gets_nothing():
    tmp = Path(tempfile.mkdtemp())
    seen = []
    server, path = _serve(tmp, lambda m, p, b: seen.append(p) or (200, "{}"), allowed_uids=set())
    env, old = _client(path)
    try:
        assert ha_client.get_state("light.kitchen") is None
        assert seen == []
    finally:
        _restore(env, old)
        server.shutdown()
        server.server_close()


def test_a_root_service_with_the_token_never_uses_the_broker():
    env, old = _client(__file__)          # no token, no override; the socket path exists
    os.environ["SUPERVISOR_TOKEN"] = "t"
    try:
        bases = [b for b, _ in ha_client._candidates()]
        assert bases == ["http://supervisor/core/api", "http://172.30.32.2/core/api"], bases
    finally:
        os.environ.pop("SUPERVISOR_TOKEN", None)   # _restore re-sets only saved values
        _restore(env, old)


def test_no_broker_and_no_token_means_unreachable_not_a_crash():
    env, old = _client("/nonexistent/ha.sock")
    try:
        assert list(ha_client._candidates()) == []
        assert ha_client.get_states() == []
    finally:
        _restore(env, old)


# --- the plumbing that keeps the token from uid 100 -------------------------

def test_uid100_execs_drop_both_token_variables():
    for svc in ("asterisk", "whisper-server"):
        execs = [l.strip() for l in (S6 / svc / "run").read_text().splitlines()
                 if l.strip().startswith("exec ") and "s6-setuidgid asterisk" in l]
        assert execs, svc
        for line in execs:
            assert line.startswith("exec env -u SUPERVISOR_TOKEN -u HASSIO_TOKEN "), (svc, line)


def test_the_s6_environment_copy_is_made_root_only_before_anything_starts():
    up = (S6 / "init-switchboard" / "up").read_text()
    assert up.startswith('/bin/sh -c "chmod 0700 /run/s6/container_environment; /usr/bin/switchboard-config && '), up


def test_the_broker_is_a_supervised_service_after_init():
    d = S6 / "ha-broker"
    assert (d / "type").read_text() == "longrun\n"
    assert (d / "dependencies.d" / "init-switchboard").exists()
    assert (S6 / "user" / "contents.d" / "ha-broker").exists()
    run = (d / "run").read_text()
    assert "exec python3 -B /usr/share/switchboard/webui/ha_broker.py" in run
    assert "s6-setuidgid" not in run, "the broker holds the token, so it runs as root"
    assert "chmod +x /etc/s6-overlay/s6-rc.d/ha-broker/run" in (ADDON / "Dockerfile").read_text()
    # Asterisk must not wait on it: a broker fault may cost HA features, never calls.
    assert not (S6 / "asterisk" / "dependencies.d" / "ha-broker").exists()


# --- what a read hands back -------------------------------------------------

STATES = [
    {"entity_id": "camera.front_door", "state": "idle", "attributes": {
        "access_token": "secret-token", "entity_picture": "/api/camera_proxy/camera.front_door?token=secret-token",
        "friendly_name": "Front door"}},
    {"entity_id": "device_tracker.phone", "state": "home", "attributes": {"latitude": 32.2, "longitude": -110.9}},
    {"entity_id": "climate.hall", "state": "heat", "last_changed": "x",
     "attributes": {"friendly_name": "Hall", "current_temperature": 68, "hvac_modes": ["heat"]}},
]


def test_state_reads_carry_only_what_the_callers_use():
    st, text = broker.filter_reply("GET", "/states", 200, json.dumps(STATES))
    out = json.loads(text)
    assert st == 200 and "secret-token" not in text and "latitude" not in text and "last_changed" not in text
    assert out[2] == {"entity_id": "climate.hall", "state": "heat",
                      "attributes": {"friendly_name": "Hall", "current_temperature": 68}}
    st, text = broker.filter_reply("GET", "/states/camera.front_door", 200, json.dumps(STATES[0]))
    assert "secret-token" not in text and json.loads(text)["state"] == "idle"
    # The caller that reads them still gets what it needs.
    real = ha_client._request
    ha_client._request = lambda m, p, b=None: broker.filter_reply(m, p, 200, json.dumps(STATES))
    try:
        import ha_reports
        climates = [s for s in ha_client.get_states() if s["entity_id"].startswith("climate.")]
        assert climates[0]["attributes"]["current_temperature"] == 68
    finally:
        ha_client._request = real


def test_the_config_read_is_only_the_location():
    full = {"latitude": 32.2, "longitude": -110.9, "unit_system": {"temperature": "°F", "length": "mi"},
            "allowlist_external_dirs": ["/config"], "components": ["a"], "internal_url": "http://x"}
    st, text = broker.filter_reply("GET", "/config", 200, json.dumps(full))
    assert json.loads(text) == {"latitude": 32.2, "longitude": -110.9, "unit_system": {"temperature": "°F"}}


def test_an_unparseable_read_is_withheld_not_passed_through():
    assert broker.filter_reply("GET", "/states", 200, "<html>proxy error</html>") == (502, "")
    # Writes and non-200s pass untouched.
    assert broker.filter_reply("POST", "/states/sensor.switchboard_last_call", 200, "ok") == (200, "ok")
    assert broker.filter_reply("GET", "/states", 401, "no") == (401, "no")


def test_a_clip_must_come_from_this_host_and_port():
    body = lambda url: {"entity_id": "media_player.k", "media_content_id": url, "media_content_type": "music"}
    path = "/services/media_player/play_media"
    assert broker.check("POST", path, body("http://192.0.2.10:8099/announce/a1.wav")) is None
    assert broker.check("POST", path, body("http://198.51.100.7:8099/announce/a1.wav"))
    assert broker.check("POST", path, body("http://192.0.2.10:22/announce/a1.wav"))
    assert broker.check("POST", path, body("http://attacker.example.net:8099/announce/a1.wav"))


def test_the_broker_never_forwards_to_itself():
    # Importing the broker turns ha_client's broker route off in its own process.
    assert ha_client.BROKER_SOCKET == "", ha_client.BROKER_SOCKET
    env, old = _client("")
    try:
        assert list(ha_client._candidates()) == []
    finally:
        _restore(env, old)


def test_the_warm_up_stops_once_home_assistant_answers():
    calls = []
    real = ha_client.available
    ha_client.available = lambda: calls.append(1) or True
    try:
        broker._warm(stop_after=5)
        assert calls == [1]
    finally:
        ha_client.available = real


def test_a_broker_that_is_down_is_logged():
    import io
    import contextlib
    env, old = _client("/nonexistent-dir/ha.sock")
    err = io.StringIO()
    try:
        with contextlib.redirect_stderr(err):
            assert ha_client.get_states() == []
    finally:
        _restore(env, old)
    assert "no Home Assistant token and no broker" in err.getvalue(), err.getvalue()

